function utf8Bytes(s) {
  const enc = encodeURIComponent(s), out=[];
  for(let i=0;i<enc.length;i++) {
    if(enc[i]==='%'){out.push(parseInt(enc.slice(i+1,i+3),16));i+=2;}
    else out.push(enc.charCodeAt(i));
  }
  return out;
}
