// Graph /me verifies the caller's Microsoft delegated access token.
// Only a student account matching the QR submission may write to Qwickly.
// A Microsoft Graph token with delegated User.Read is required (not an ID token).
const source=$('07 · QR Validation / Session / Roster / Export').first().json;
const graphReply=$input.first().json;
const graph=graphReply.body && typeof graphReply.body==='object'?graphReply.body:{};
const reject=(status,message,code)=>[{json:{...source,kind:'json',httpStatus:status,needsWrite:false,needsProxy:false,canProxy:false,writeRow:null,payload:{ok:false,success:false,demo:false,recordedInQwickly:false,status:code,message}}}];
if(Number(graphReply.statusCode)!==200||!graph.id)return reject(401,'Microsoft Graph could not verify the signed-in account. Sign out and sign in again with User.Read permission.','microsoft_auth_failed');
const accounts=[graph.userPrincipalName,graph.mail].filter(x=>typeof x==='string').map(x=>x.trim().toLowerCase());
const match=accounts.map(x=>/^([0-9]{6,12})@students\.swinburne\.edu\.my$/.exec(x)).find(Boolean);
if(!match)return reject(403,'A verified Swinburne student account is required.','not_student');
const actualSis=match[1];
if(actualSis!==String(source.writeRow?.sis_id||''))return reject(403,'Signed-in Microsoft student identity does not match the submitted SIS ID.','student_mismatch');
const sessionId=String($('05 · Request Context').first().json.sessionKey).split('|')[1];
const courseId=String($('05 · Request Context').first().json.sessionKey).split('|')[0];
// The proxy guide explicitly supports sis_id. Use id only when you have an authorised Qwickly user-ID mapping.
const proxyBody={user_identifier:'sis_id',user_value:actualSis,status_id:286,comment:null,make_comment_public:false,location_context:1};
const writeRow={...source.writeRow,student_name:String(graph.displayName||('Student '+actualSis)).slice(0,100)};
return [{json:{...source,writeRow,canProxy:true,needsProxy:true,proxyBody,courseId,sessionId}}];

// Only HTTP 201 from the authorised Qwickly proxy is a newly recorded attendance.
// This node NEVER marks unconfirmed records as successful.
const ctx=$('20 · Verify Student SIS / Prepare Qwickly POST').first().json;
const api=$input.first().json;
const statusCode=Number(api.statusCode||0);
const record=api.body&&typeof api.body==='object'?api.body:{};
const fail=(httpStatus,message,status)=>[{json:{kind:'json',httpStatus,needsWrite:false,needsProxy:false,payload:{ok:false,success:false,demo:false,recordedInQwickly:false,status,message,courseCode:'CSS202',sessionId:ctx.sessionId}}}];
if(statusCode===409)return fail(409,'This student already has a Qwickly attendance record for this class.', 'already_recorded');
if(statusCode!==201){
 const status=[400,401,403,404,409,429,502,503].includes(statusCode)?statusCode:502;
 return fail(status,'Qwickly did not confirm the attendance POST (proxy HTTP '+String(statusCode||'unknown')+'). Check proxy credentials, session and student mapping.','qwickly_post_failed');
}
if(!Number.isSafeInteger(Number(record.id))||!Number.isSafeInteger(Number(record.parent_session))||Number(record.parent_session)!==Number(ctx.sessionId)||Number(record.status_id)!==286){
 return fail(502,'The proxy returned HTTP 201 but the Qwickly record could not be verified. Check Qwickly before retrying.','unverified_qwickly_response');
}
const time=String(record.time_created||new Date().toISOString());
const writeRow={...ctx.writeRow,student_name:ctx.writeRow.student_name,status:'PRESENT_QWICKLY',scanned_at:time,record_json:JSON.stringify(record)};
return [{json:{kind:'json',httpStatus:201,needsWrite:true,needsProxy:false,writeRow,payload:{ok:true,success:true,status:'qwickly_recorded',message:'Attendance recorded in Qwickly.',demo:false,recordedInQwickly:true,courseCode:'CSS202',courseLmsId:ctx.courseId,sessionId:ctx.sessionId,sisId:writeRow.sis_id,studentName:writeRow.student_name,scannedAt:time,record}}}];
